window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-41401\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερέκχυσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 395 na letra υ · nº geral 41401</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 maré alta 2 fluxo excessivo; transbordamento; inundação. 〈ὑπερεκχέομαι〉</p></section></article>\n<article id=\"entry-dgp-41402\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεμπίπλημι</h1><div class=\"entry-meta\"><span>DGP · ordem 396 na letra υ · nº geral 41402</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encher por cima da borda; fazer transbordar ♦ pas. 2 estar cheio de algo, gen., de modo a transbordar.</p></section></article>\n<article id=\"entry-dgp-41403\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεμφορέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 397 na letra υ · nº geral 41403</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fartar-se; saciar-se de, gen.</p></section></article>\n<article id=\"entry-dgp-41404\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεντυγχάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 398 na letra υ · nº geral 41404</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">interceder por, gen. ou ὑπέρ e gen.</p></section></article>\n<article id=\"entry-dgp-41405\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεξαπατάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 399 na letra υ · nº geral 41405</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">enganar excessivamente.</p></section></article>\n<article id=\"entry-dgp-41406\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεξάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 400 na letra υ · nº geral 41406</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inflamar excessivamente.</p></section></article>\n<article id=\"entry-dgp-41407\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεπαινέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 401 na letra υ · nº geral 41407</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">elogiar, louvar excessivamente.</p></section></article>\n<article id=\"entry-dgp-41408\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεπιθυμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 402 na letra υ · nº geral 41408</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter o maior desejo de; desejar demais, inf.</p></section></article>\n<article id=\"entry-dgp-41409\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερέπτατο</h1><div class=\"entry-meta\"><span>DGP · ordem 403 na letra υ · nº geral 41409</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. aor. de ὑπερίπταμαι.</p></section></article>\n<article id=\"entry-dgp-41410\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερέπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 404 na letra υ · nº geral 41410</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 minar sob; escavar (areia) 2 minar no íntimo; minar interiormente.</p></section></article>\n<article id=\"entry-dgp-41411\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεράομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 405 na letra υ · nº geral 41411</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ὑπερηράσθην) amar apaixonadamente, gen.</p></section></article>\n<article id=\"entry-dgp-41412\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερέρχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 406 na letra υ · nº geral 41412</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 passar por cima; atravessar; transpor, ac. 2 levar a melhor; vencer em algo, dat.</p></section></article>\n<article id=\"entry-dgp-41413\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεσθίω</h1><div class=\"entry-meta\"><span>DGP · ordem 407 na letra υ · nº geral 41413</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑπερέδομαι) comer excessivamente.</p></section></article>\n<article id=\"entry-dgp-41414\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερέσχεθο</h1><div class=\"entry-meta\"><span>DGP · ordem 408 na letra υ · nº geral 41414</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. aor.2 ép. de ὑπερέχω.</p></section></article>\n<article id=\"entry-dgp-41415\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρευ</h1><div class=\"entry-meta\"><span>DGP · ordem 409 na letra υ · nº geral 41415</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. da melhor maneira possível; muito bem. 〈ὑπέρ, εὖ〉</p></section></article>\n<article id=\"entry-dgp-41416\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρευγε</h1><div class=\"entry-meta\"><span>DGP · ordem 410 na letra υ · nº geral 41416</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. muito bem; excelentemente; às mil maravilhas. 〈ὑπέρ, εὖγε〉</p></section></article>\n<article id=\"entry-dgp-41417\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερευδαιμονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 411 na letra υ · nº geral 41417</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estar muito feliz.</p></section></article>\n<article id=\"entry-dgp-41418\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερευδαίμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 412 na letra υ · nº geral 41418</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος excessivamente ou muito feliz.</p></section></article>\n<article id=\"entry-dgp-41419\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερευφραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 413 na letra υ · nº geral 41419</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 regozijar-se demais com algo, ac. 2 experimentar uma alegria imensa por ou com, ac. ou ἐπί e dat.</p></section></article>\n<article id=\"entry-dgp-41420\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεύωνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 414 na letra υ · nº geral 41420</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito barato. 〈ὑπέρ, εὔωνος〉</p></section></article>\n<article id=\"entry-dgp-41421\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερεχθαίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 415 na letra υ · nº geral 41421</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">odiar com paixão.</p></section></article>\n<article id=\"entry-dgp-41422\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερέχω</h1><div class=\"entry-meta\"><span>DGP · ordem 416 na letra υ · nº geral 41422</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑπερέξω, aor.2 ὑπερέσχον, subj. aor.2 ὑπέρσχω, opt. aor.2 ὑπέρσχοιμι, inf. aor.2 ὑπερσχεῖν, part. aor.2 ὑπερσχών) 1 manter acima; manter elevado ou suspenso sobre: σπλάγχνα ὑπ. Ἡφαίστοιο hom. suster as entranhas acima do fogo de Hefesto, τὴν κεφαλὴν ὑπ. τοῦ ὄρνιθος ar. manter erguida a cabeça do pássaro, ὑπ. χεῖρας ou χεῖρα hom. suster as mãos ou a mão sobre alguém, dat. ou gen., para protegê-lo 2 manter-se acima de; elevar-se acima de, gen.: τὰ ὑπερέχοντα her. as partes dominantes ou salientes 3 despontar; emergir de, gen. 4 (mar, líquido) estar em nível mais alto; elevar-se 5 avançar lateralmente; ocupar maior espaço: ὅπως ὑπερέχοιεν τῷ κέρατι τῶν πολεμίων xen. para avançar com a ala sobre os inimigos 6 estar acima de (em estatura); sobrepujar; exceder; dominar: στάντων μὲν Μενέλαος ὑπείρεχεν εὐρέας ὤμους hom. estando ambos em pé, Menelau [a Odisseu] excedia pelos largos ombros 7 levar vantagem; levar a melhor; sobrepujar; ser superior a alguém, ac., em algo, dat. ou gen. ou part. predic.: ὑπερέχει λέγων luc. leva a melhor nas discussões 8 dominar; prevalecer 9 exceder; distinguir-se; destacar-se ♦ pas. 10 ser superado, sobrepujado: ὑπό Φαίδωνος ὑπερέχεσθαι plat. ser superado por Fédon. 〈ὑπέρ, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-41423\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 417 na letra υ · nº geral 41423</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. irreg. de ὑπαγορεύω.</p></section></article>\n<article id=\"entry-dgp-41424\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερζέω</h1><div class=\"entry-meta\"><span>DGP · ordem 418 na letra υ · nº geral 41424</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ferver em demasia; ser fervente 2 ferver; excitar-se; exacerbar-se de (cólera, vida), dat. 3 (sol) ser ardente.</p></section></article>\n<article id=\"entry-dgp-41425\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερηδέως</h1><div class=\"entry-meta\"><span>DGP · ordem 419 na letra υ · nº geral 41425</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com o maior prazer; com muito gosto. 〈ὑπέρηδυς〉</p></section></article>\n<article id=\"entry-dgp-41426\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρηδυς, υς, υ</h1><div class=\"entry-meta\"><span>DGP · ordem 420 na letra υ · nº geral 41426</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. εος (superl. ὑπερήδιστος) extremamente agradável; muito prazeroso. 〈ὑπέρ, ἡδύς〉</p></section></article>\n<article id=\"entry-dgp-41427\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερήδω</h1><div class=\"entry-meta\"><span>DGP · ordem 421 na letra υ · nº geral 41427</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 alegrar, divertir extremamente ♦ pas. 2 alegrar-se, divertir-se excessiva ou extremamente.</p></section></article>\n<article id=\"entry-dgp-41428\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερήμερος, ος,</h1><div class=\"entry-meta\"><span>DGP · ordem 422 na letra υ · nº geral 41428</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ον 1 Jur. que ultrapassa o dia fixado para o acerto do pagamento de uma dívida: ὑπ. γενέσθαι lís. tornar-se devedor que atrasa no pagamento da dívida, λαμβάνειν τινὰ ὑπερήμενον dem. conseguir o direito de assumir os bens de alguém por falta de pagamento dentro do prazo 2 que está em atraso pelo prazo; que deixa passar o prazo fixado para, gen. 3 que adia, prorroga uma pena (juiz) 4 que dura ou durou além do tempo justo; que passou o limite da vida. 〈ὑπέρ, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-41429\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερήμισυς, υς, υ</h1><div class=\"entry-meta\"><span>DGP · ordem 423 na letra υ · nº geral 41429</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. εος que passa da metade; que passa do meio.</p></section></article>\n<article id=\"entry-dgp-41430\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρημος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 424 na letra υ · nº geral 41430</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">quase deserto. 〈ὑπό, ἔρημος〉</p></section></article>\n<article id=\"entry-dgp-41431\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερηνορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 425 na letra υ · nº geral 41431</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. ὑπερηνορέων, οντος) poét. ser orgulhoso de sua força; ser arrogante. 〈ὑπερήνωρ〉</p></section></article>\n<article id=\"entry-dgp-41432\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερήνωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 426 na letra υ · nº geral 41432</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc. fem.) que se orgulha de sua força; orgulhoso; arrogante; prepotente. 〈ὑπέρ, ἀνήρ〉</p></section></article>\n<article id=\"entry-dgp-41433\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερήσει</h1><div class=\"entry-meta\"><span>DGP · ordem 427 na letra υ · nº geral 41433</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. fut. de ὑπερίημι.</p></section></article>\n<article id=\"entry-dgp-41434\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερηφανέστατος</h1><div class=\"entry-meta\"><span>DGP · ordem 428 na letra υ · nº geral 41434</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ὑπερήφανος.</p></section></article>\n<article id=\"entry-dgp-41435\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερηφανέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 429 na letra υ · nº geral 41435</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser orgulhoso, desdenhoso; comportar-se arrogantemente com alguém, ἐπί e ac. 2 tratar com desprezo, desdém ou arrogância; desdenhar de; desprezar, ac. 3 exaltar: ὑπ. ἑαυτοὺς καὶ τὰς ἰδίας πραγματείας pol. exaltar a si próprios e às obras. 〈ὑπερήφανος〉</p></section></article>\n<article id=\"entry-dgp-41436\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερηφανία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 430 na letra υ · nº geral 41436</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">orgulho; desdém. 〈ὑπερήφανος〉</p></section></article>\n<article id=\"entry-dgp-41437\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερήφανος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 431 na letra υ · nº geral 41437</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 magnífico; esplêndido 2 orgulhoso; soberbo; arrogante ♦ τὸ ὑπερήφανον 3 orgulho. 〈ὑπέρ, φαίνω〉</p></section></article>\n<article id=\"entry-dgp-41438\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερηφάνως</h1><div class=\"entry-meta\"><span>DGP · ordem 432 na letra υ · nº geral 41438</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com magnificência 2 com prodigalidade; suntuosamente 3 com orgulho ou arrogância.</p></section></article>\n<article id=\"entry-dgp-41439\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθαλασσίδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 433 na letra υ · nº geral 41439</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">situado do outro lado do mar; de além dos mares, de ultramar. 〈ὑπέρ, θάλασσα〉</p></section></article>\n<article id=\"entry-dgp-41440\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθαυμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 434 na letra υ · nº geral 41440</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar admirado em excesso; estar atônito, pasmado, ac. 2 admirar grandemente; maravilhar-se com, ac.</p></section></article>\n<article id=\"entry-dgp-41441\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕπερθε</h1><div class=\"entry-meta\"><span>DGP · ordem 435 na letra υ · nº geral 41441</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ou ὕπερθεν adv. 1 do alto; do céu 2 no alto; acima 3 muito mais; mais fortemente; mais gravemente: μόχθων δ᾽ οὐκ ἄλλος ὕπ. ἢ γᾶς πατρίας στέρεσθαι eur. dos tormentos nenhum mais grave do que estar privado da terra pátria ♦ prep. 4 acima de; no alto de, gen.: ὕπερθεν μόχθων ἐγένετο eur. superou as fadigas. 〈ὑπέρ, -θε〉</p></section></article>\n<article id=\"entry-dgp-41442\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθερμαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 436 na letra υ · nº geral 41442</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esquentar muito.</p></section></article>\n<article id=\"entry-dgp-41443\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 437 na letra υ · nº geral 41443</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 correr por cima ou além; transpor correndo, ac. 2 superar; ultrapassar; vencer.</p></section></article>\n<article id=\"entry-dgp-41444\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθήσω</h1><div class=\"entry-meta\"><span>DGP · ordem 438 na letra υ · nº geral 41444</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de ὑπερτίθημι.</p></section></article>\n<article id=\"entry-dgp-41445\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθνῄσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 439 na letra υ · nº geral 41445</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">morrer por ou por causa de, gen.</p></section></article>\n<article id=\"entry-dgp-41446\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθορεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 440 na letra υ · nº geral 41446</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de ὑπερθρῴσκω.</p></section></article>\n<article id=\"entry-dgp-41447\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθρῴσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 441 na letra υ · nº geral 41447</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑπερθοροῦμαι, aor.2 ὑπερέθορον etc.) 1 saltar ou pular por cima; transpor com um salto, ac. 2 fugir de; evitar, ac.</p></section></article>\n<article id=\"entry-dgp-41448\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρθυμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 442 na letra υ · nº geral 41448</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de coragem ou de ardor; corajoso; magnânimo 2 impetuoso; violento; prepotente 3 fortemente irado; agastado; zangado 4 fogoso (cavalo). 〈ὑπέρ, θυμός〉</p></section></article>\n<article id=\"entry-dgp-41449\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθύριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 443 na letra υ · nº geral 41449</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pedra ou viga transversal acima de uma porta. 〈ὑπέρθυρος〉</p></section></article>\n<article id=\"entry-dgp-41450\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρθυρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 444 na letra υ · nº geral 41450</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 situado, colocado acima de uma porta ♦ τὸ ὑπέρθυρον 2 = ὑπερθύριον. 〈ὑπέρ, θύρα〉</p></section></article>\n<article id=\"entry-dgp-41451\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερθωμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 445 na letra υ · nº geral 41451</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ὑπερθαυμάζω.</p></section></article>\n<article id=\"entry-dgp-41452\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπεριδεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 446 na letra υ · nº geral 41452</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de ὑπεροράω.</p></section></article>\n<article id=\"entry-dgp-41453\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερίημι</h1><div class=\"entry-meta\"><span>DGP · ordem 447 na letra υ · nº geral 41453</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑπερήσω, aor. ὑπερῆκα etc.) jogar longe; lançar além do ponto alcançado por um concorrente.</p></section></article>\n<article id=\"entry-dgp-41454\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερικταίνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 448 na letra υ · nº geral 41454</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. 3a pl. ὑπερικταίνοντο) ir a toda a pressa ou vivamente; apressar-se. 〈ὑπέρ, ἱκνέομαι〉</p></section></article>\n<article id=\"entry-dgp-41455\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερίπταμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 449 na letra υ · nº geral 41455</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑπερπτήσομαι, aor.1 ὑπερεπτάμην, aor.2 ὑπερέπτην) voar por cima de, além de, ac.</p></section></article>\n<article id=\"entry-dgp-41456\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερίσταμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 450 na letra υ · nº geral 41456</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑπερστήσομαι, aor.2 ὑπερέστην etc.) 1 pôr-se ou manter-se acima de ou diante de, gen. 2 pôr-se em proteção ou em defesa; proteger-se; defender-se de, gen. 3 superar; ser maior ou mais pesado do que, gen. 〈ὑπέρ, ἵστημι〉</p></section></article>\n<article id=\"entry-dgp-41457\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερίστωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 451 na letra υ · nº geral 41457</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc. fem.) que sabe muito bem; ciente; cônscio de, gen. 〈ὑπέρ, ἵστωρ〉</p></section></article>\n<article id=\"entry-dgp-41458\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερίσχυρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 452 na letra υ · nº geral 41458</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">extremamente forte ou sólido. 〈ὑπέρ, ἰσχυρός〉</p></section></article>\n<article id=\"entry-dgp-41459\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκάθημαι</h1><div class=\"entry-meta\"><span>DGP · ordem 453 na letra υ · nº geral 41459</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 estar acampado acima de, ἐπί e gen. 2 estar nos calcanhares ou nas costas de alguém; vigiar; ter sob a vista; pressionar vivamente, gen.</p></section></article>\n<article id=\"entry-dgp-41460\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκαλλής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 454 na letra υ · nº geral 41460</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">extraordinariamente belo; de uma beleza extraordinária. 〈ὑπέρ, κάλλος〉</p></section></article>\n<article id=\"entry-dgp-41461\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκάμνω</h1><div class=\"entry-meta\"><span>DGP · ordem 455 na letra υ · nº geral 41461</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑπερκαμοῦμαι, aor.2 ὑπερέκαμον etc.) trabalhar ou sofrer por, gen.</p></section></article>\n<article id=\"entry-dgp-41462\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκαταβαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 456 na letra υ · nº geral 41462</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">descer pelo alto; saltar além de; transpor, ac. ou gen.</p></section></article>\n<article id=\"entry-dgp-41463\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκαταγέλαστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 457 na letra υ · nº geral 41463</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">extrememente ridículo; absurdo.</p></section></article>\n<article id=\"entry-dgp-41464\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκατάκειμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 458 na letra υ · nº geral 41464</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estar reclinado à mesa acima de alguém; estar sobre; ocupar posto superior.</p></section></article>\n<article id=\"entry-dgp-41465\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκατηφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 459 na letra υ · nº geral 41465</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito abatido 2 em mau estado (coisa).</p></section></article>\n<article id=\"entry-dgp-41466\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκαχλάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 460 na letra υ · nº geral 41466</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">referver; transbordar fervendo; espumar.</p></section></article>\n<article id=\"entry-dgp-41467\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρκειμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 461 na letra υ · nº geral 41467</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser colocado ou estar por cima, no alto de, gen. ou dat. 2 ser superior; superar, ac. 3 ser adiado ou ser posto de parte.</p></section></article>\n<article id=\"entry-dgp-41468\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκεράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 462 na letra υ · nº geral 41468</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superar com as alas ou uma ala do exército, ac. 〈ὑπέρ, κέρας〉</p></section></article>\n<article id=\"entry-dgp-41469\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρκομπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 463 na letra υ · nº geral 41469</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se gaba excessivamente; orgulhoso; presunçoso 2 extraordinário; notável. 〈ὑπέρ, κόμπος〉</p></section></article>\n<article id=\"entry-dgp-41470\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρκοπος1, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 464 na letra υ · nº geral 41470</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ultrapassa o limite; soberbo; arrogante; presunçoso 2 extraordinário; excelente. 〈ὑπέρ, κόπτω〉</p></section></article>\n<article id=\"entry-dgp-41471\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρκοπος2, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 465 na letra υ · nº geral 41471</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">demasiadamente cansado; esgotado. 〈ὑπέρ, κόπος〉</p></section></article>\n<article id=\"entry-dgp-41472\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκόπως</h1><div class=\"entry-meta\"><span>DGP · ordem 466 na letra υ · nº geral 41472</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com arrogância.</p></section></article>\n<article id=\"entry-dgp-41473\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκτάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 467 na letra υ · nº geral 41473</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adquirir a mais, em acréscimo.</p></section></article>\n<article id=\"entry-dgp-41474\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκύδας, αντος</h1><div class=\"entry-meta\"><span>DGP · ordem 468 na letra υ · nº geral 41474</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) muito célebre; glorioso. 〈ὑπέρ, κῦδος〉</p></section></article>\n<article id=\"entry-dgp-41475\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερκύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 469 na letra υ · nº geral 41475</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 debruçar-se sobre; inclinar-se para olhar fora de, gen. 2 avançar para ver; avançar para fora ou além de; adiantar-se 3 ultrapassar; exceder; superar; dominar, ac.</p></section></article>\n<article id=\"entry-dgp-41476\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρλαμπρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 470 na letra υ · nº geral 41476</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito brilhante; resplandecente ♦ adv. ὑπέρλαμπρον 2 com grandes brados; com voz muito alta. 〈ὑπέρ, λαμπρός〉</p></section></article>\n<article id=\"entry-dgp-41477\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρλευκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 471 na letra υ · nº geral 41477</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de brancura deslumbrante. 〈ὑπέρ, λευκός〉</p></section></article>\n<article id=\"entry-dgp-41478\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερλίαν</h1><div class=\"entry-meta\"><span>DGP · ordem 472 na letra υ · nº geral 41478</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., bíbl. excessivamente; superiormente.</p></section></article>\n<article id=\"entry-dgp-41479\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερλυπέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 473 na letra υ · nº geral 41479</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">causar profunda tristeza; afligir vivamente.</p></section></article>\n<article id=\"entry-dgp-41480\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμαζάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 474 na letra υ · nº geral 41480</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar alimentado com uma massa muito substanciosa; estar inchado 2 estar cheio de si; ser orgulhoso, presunçoso. 〈ὑπέρ, μᾶζα〉</p></section></article>\n<article id=\"entry-dgp-41481\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 475 na letra υ · nº geral 41481</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combater por; tomar a defesa de, gen. 〈ὑπέρ, μάχη〉</p></section></article>\n<article id=\"entry-dgp-41482\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμαχητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 476 na letra υ · nº geral 41482</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pronto para combater por ou em defesa de; capaz de proteger, gen. 〈ὑπερμαχέω〉</p></section></article>\n<article id=\"entry-dgp-41483\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμάχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 477 na letra υ · nº geral 41483</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑπερμαχέσομαι, át. ὑπερμαχοῦμαι, aor. ὑπερεμαχεσάμην) combater por; tomar a defesa de, gen.</p></section></article>\n<article id=\"entry-dgp-41484\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμεγάθης</h1><div class=\"entry-meta\"><span>DGP · ordem 478 na letra υ · nº geral 41484</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ὑπερμεγέθης.</p></section></article>\n<article id=\"entry-dgp-41485\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμέγας, ὑπερμεγάλη, ὑπερμέγα</h1><div class=\"entry-meta\"><span>DGP · ordem 479 na letra υ · nº geral 41485</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">excessivamente grande.</p></section></article>\n<article id=\"entry-dgp-41486\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμεγέθης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 480 na letra υ · nº geral 41486</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de tamanho desmedido; excessivamente grande; enorme 2 muito árduo; difícil. 〈ὑπέρ, μέγεθος〉</p></section></article>\n<article id=\"entry-dgp-41487\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμεθύσκομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 481 na letra υ · nº geral 41487</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. ὑπερμεθυσθῆναι) embriagar-se em excesso.</p></section></article>\n<article id=\"entry-dgp-41488\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμενέων, οντος</h1><div class=\"entry-meta\"><span>DGP · ordem 482 na letra υ · nº geral 41488</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) orgulhoso; arrogante. 〈ὑπερμενής〉</p></section></article>\n<article id=\"entry-dgp-41489\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 483 na letra υ · nº geral 41489</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito forte; muito poderoso; onipotente (Zeus). 〈ὑπέρ, μένος〉</p></section></article>\n<article id=\"entry-dgp-41490\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρμετρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 484 na letra υ · nº geral 41490</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que excede a medida; desmedido; excessivo 2 que ultrapassa a medida de um verso; muito longo; hipermétrico. 〈ὑπέρ, μέτρον〉</p></section></article>\n<article id=\"entry-dgp-41491\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμήχης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 485 na letra υ · nº geral 41491</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de comprimento enorme; longuíssimo 2 de altura excessiva; altíssimo 3 muito forte; rumoroso (grito). 〈ὑπέρ, μῆκος〉</p></section></article>\n<article id=\"entry-dgp-41492\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερμισέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 486 na letra υ · nº geral 41492</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">odiar sobremaneira, acima de qualquer medida.</p></section></article>\n<article id=\"entry-dgp-41493\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρμορα</h1><div class=\"entry-meta\"><span>DGP · ordem 487 na letra υ · nº geral 41493</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = ὑπέρμορον.</p></section></article>\n<article id=\"entry-dgp-41494\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρμορον</h1><div class=\"entry-meta\"><span>DGP · ordem 488 na letra υ · nº geral 41494</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. que está além das determinações do destino; contra o destino. 〈ὑπέρ, μόρον〉</p></section></article>\n<article id=\"entry-dgp-41495\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερνέφελος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 489 na letra υ · nº geral 41495</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que está ou se eleva acima das nuvens. 〈ὑπέρ, νεφέλη〉</p></section></article>\n<article id=\"entry-dgp-41496\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερνεωλκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 490 na letra υ · nº geral 41496</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tirar (navio), ac., do mar e levá-lo para a terra; arrastar pela terra.</p></section></article>\n<article id=\"entry-dgp-41497\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερνικάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 491 na letra υ · nº geral 41497</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. vencer completamente; ter uma gloriosa vitória.</p></section></article>\n<article id=\"entry-dgp-41498\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερνοέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 492 na letra υ · nº geral 41498</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">refletir ou meditar sobre; preocupar-se com, ac.</p></section></article>\n<article id=\"entry-dgp-41499\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερνότιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 493 na letra υ · nº geral 41499</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 situado além do vento Noto, para além do Sul ou no extremo Sul ♦ οἱ Ὑπερνότιοι 2 os povos do extremo Sul. 〈ὑπέρ, νότος〉</p></section></article>\n<article id=\"entry-dgp-41500\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρογκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 494 na letra υ · nº geral 41500</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 excessivamente inchado 2 carregado de gordura; muito gordo; corpulento 3 empolado; pomposo; enfático; verboso (estilo) 4 enorme; desmedido 5 muito difícil ou árduo 6 cheio de si; orgulhoso. 〈ὑπέρ, ὄγκος〉</p></section></article>\n";
